pragma solidity ^0.8.36;
contract C {
    function stopped() internal pure {
        return;
        {}
    }
    function recursive() internal returns (uint256) {
        (uint256 value) = recursive();
        value;
    }
    function forceLaterPhase() public pure returns (uint256) {
        return addmod(1, 2, 0);
    }
}
